from math import comb

def R(n):
    if n < 4:
        return 0
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)
    if f_kn == 0:
        return float('inf')
    return g_kn**3 / f_kn**4

results = {}
for n in range(4, 9):
    results[n] = R(n)

print("n=4: %.10f" % results[4])
print("n=5: %.10f" % results[5])
print("n=6: %.10f" % results[6])
print("n=7: %.10f" % results[7])
print("n=8: %.10f" % results[8])

# Calculate fractions for clean presentation
def calc_ratio(n):
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)
    if f_kn == 0:
        return None
    num = g_kn**3
    den = f_kn**4
    return f"{num}/{den}"

print("\nFractions:")
for n in range(4, 9):
    print(f"n={n}: {calc_ratio(n)}")
